def seed_world():
    # Frozen seed data: future changes belong in a new revision.
    """마이그레이션 대상의 기존 구조와 데이터를 확인하고 반영한다."""
    item = sa.table('item', sa.column('id',sa.Integer()), sa.column('name',sa.String()),
        sa.column('description',sa.Text()), sa.column('weight_grams',sa.Integer()), sa.column('kind',sa.String()))
    insert_seed_if_missing(item, [
        {'id':1,'name':'정체를 알 수 없는 버섯','description':'축축한 나무뿌리 옆에서 자라는 버섯. 아직 용도를 알 수 없다.','weight_grams':200,'kind':'farming'},
        {'id':2,'name':'희미한 빛을 띄는 버섯','description':'작은 빛을 머금은 희귀한 버섯. 마나가 느껴진다.','weight_grams':150,'kind':'farming'},
        {'id':3,'name':'붉은 잎 약초','description':'숲 깊은 곳에서 자라는 붉은 약초.','weight_grams':300,'kind':'farming'},
        {'id':4,'name':'푸른 마나 열매','description':'푸른 마나가 응축된 작은 열매.','weight_grams':500,'kind':'farming'},
    ])
    farming = sa.table('farming_item',sa.column('item_id',sa.Integer()))
    insert_seed_if_missing(farming,[{'item_id':index} for index in range(1,5)])
    world_map = sa.table('map',sa.column('id',sa.Integer()),sa.column('name',sa.String()),
        sa.column('description',sa.Text()),sa.column('empty_weight',sa.Integer()))
    insert_seed_if_missing(world_map,[
        {'id':1,'name':'깊은 숲1','description':'숲 가장자리의 버섯 군락. 버려진 아이들이 처음 채집을 배우는 곳이다.','empty_weight':70},
        {'id':3,'name':'깊은 숲3','description':'마나가 짙게 흐르는 숲의 안쪽. 낯선 약초와 열매가 자란다.','empty_weight':55},
    ])
    link = sa.table('map_farming_item',sa.column('id',sa.Integer()),sa.column('map_id',sa.Integer()),
        sa.column('farming_item_id',sa.Integer()),sa.column('weight',sa.Integer()))
    insert_seed_if_missing(link,[{'id':1,'map_id':1,'farming_item_id':1,'weight':25},
        {'id':2,'map_id':1,'farming_item_id':2,'weight':5},
        {'id':3,'map_id':3,'farming_item_id':3,'weight':35},
        {'id':4,'map_id':3,'farming_item_id':4,'weight':10}])
    # Every existing completed character starts with an empty 10-slot / 30kg inventory.
    connection = op.get_bind()
    inventory = sa.table('inventory', sa.column('character_id',sa.Integer()),
        sa.column('slot_capacity',sa.Integer()),sa.column('max_weight_grams',sa.Integer()))
    for character_id in connection.execute(sa.text("SELECT id FROM `character` WHERE status='ready'")).scalars().all():
        if connection.execute(sa.select(inventory.c.character_id).where(inventory.c.character_id == character_id)).first() is None:
            connection.execute(inventory.insert().values(character_id=character_id,slot_capacity=10,max_weight_grams=30000))



def create_table_or_validate(name, *definitions, **kwargs):
    """MySQL DDL은 중간 실패 시 남을 수 있다. 기존 구조를 검증한 뒤 건너뛴다."""
    connection = op.get_bind()
    inspector = sa.inspect(connection)
    if not inspector.has_table(name):
        if connection.dialect.name == 'mysql':
            kwargs.setdefault('mysql_engine', 'InnoDB')
        return op.create_table(name, *definitions, **kwargs)
    expected = sa.Table(name, sa.MetaData(), *definitions)
    actual = {column['name']: column for column in inspector.get_columns(name)}
    problems = []
    for column in expected.columns:
        if column.name not in actual:
            problems.append(f'컬럼 누락: {column.name}')
            continue
        current = actual[column.name]
        if current['type']._type_affinity is not column.type._type_affinity:
            problems.append(f'컬럼 타입 불일치: {column.name}')
        if column.nullable != current['nullable']:
            problems.append(f'NULL 설정 불일치: {column.name}')
        size = getattr(column.type, 'length', None)
        actual_size = getattr(current['type'], 'length', None)
        if size is not None and actual_size is not None and actual_size < size:
            problems.append(f'컬럼 길이 부족: {column.name}')
    if set(inspector.get_pk_constraint(name)['constrained_columns']) != {column.name for column in expected.primary_key.columns}:
        problems.append('기본키 불일치')
    unique_sets = [set(item['column_names']) for item in inspector.get_unique_constraints(name)]
    unique_sets += [set(item['column_names']) for item in inspector.get_indexes(name) if item.get('unique')]
    foreign_keys = inspector.get_foreign_keys(name)
    checks = {item['name'] for item in inspector.get_check_constraints(name)}
    for constraint in expected.constraints:
        if isinstance(constraint, sa.UniqueConstraint):
            if {column.name for column in constraint.columns} not in unique_sets:
                problems.append(f'UNIQUE 누락: {list(constraint.columns.keys())}')
        elif isinstance(constraint, sa.CheckConstraint):
            if constraint.name and constraint.name not in checks:
                problems.append(f'CHECK 누락: {constraint.name}')
        elif isinstance(constraint, sa.ForeignKeyConstraint):
            targets = [element.target_fullname.rsplit('.', 1) for element in constraint.elements]
            local = [element.parent.name for element in constraint.elements]
            matching = next((key for key in foreign_keys if key['constrained_columns'] == local
                and key['referred_table'] == targets[0][0]
                and key['referred_columns'] == [target[1] for target in targets]), None)
            if matching is None:
                problems.append(f'FK 누락: {local}')
            elif constraint.ondelete == 'CASCADE' and matching.get('options', {}).get('ondelete', '').upper() != 'CASCADE':
                problems.append(f'ON DELETE CASCADE 누락: {local}')
    if connection.dialect.name == 'mysql':
        engine = inspector.get_table_options(name).get('mysql_engine', '')
        if engine.lower() != 'innodb':
            problems.append(f'InnoDB 엔진 필요: 현재 {engine}')
    if problems:
        raise RuntimeError(f'{name} 기존 구조가 달라서 변경하지 않고 중단해: ' + '; '.join(problems))
    print(f'기존 테이블 검증 후 유지: {name}')


def insert_seed_if_missing(table, rows):
    """기존 행을 덮어쓰지 않는다. 예약된 ID가 다른 데이터면 명확히 중단한다."""
    connection = op.get_bind()
    primary_key = 'item_id' if table.name == 'farming_item' else 'id'
    identity_fields = {
        'item': ['name', 'kind'], 'map': ['name'],
        'map_farming_item': ['map_id', 'farming_item_id'], 'farming_item': [],
    }[table.name]
    for row in rows:
        existing = connection.execute(sa.select(table).where(table.c[primary_key] == row[primary_key])).mappings().first()
        if existing:
            if any(existing[field] != row[field] for field in identity_fields):
                raise RuntimeError(f'{table.name}의 예약 ID {row[primary_key]}가 다른 데이터에 사용 중이야. 기존 행은 변경하지 않았어.')
            continue
        if table.name == 'map_farming_item':
            same_pair = connection.execute(sa.select(table.c.id).where(
                table.c.map_id == row['map_id'], table.c.farming_item_id == row['farming_item_id'])).first()
            if same_pair:
                continue
        connection.execute(table.insert().values(**row))
